(function () {'use strict';var form = document.getElementById('login-form');if (!form || !window.ZamoveApi) return;var statusBox = document.getElementById('login-status');var submitBtn = document.getElementById('login-submit');var label = submitBtn.textContent;var HOME = { customer: 'bookings.html', operator: 'operator.html', admin: 'admin.html' };var EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;function say(kind, msg) {statusBox.className = 'alert ' + kind;statusBox.textContent = msg;}
function fieldError(name, msg) {var el = form.elements[name], box = document.getElementById('login-' + name + '-err');box.textContent = msg || '';if (msg) el.setAttribute('aria-invalid', 'true'); else el.removeAttribute('aria-invalid');}
function busy(on) {submitBtn.disabled = on;submitBtn.setAttribute('aria-busy', on ? 'true' : 'false');submitBtn.textContent = on ? 'Logging in…' : label;}
var q = new URLSearchParams(location.search);if (q.get('expired')) say('bad', 'Your session has ended. Please log in again.');if (q.get('loggedout')) say('ok', 'You have been logged out.');function safeNext(role) {var n = q.get('next') || '';return /^[a-z0-9_-]+\.html(\?[A-Za-z0-9=&_.-]{0,100})?$/i.test(n) && n.indexOf('login.html') !== 0 ? n : HOME[role] || 'index.html';}
form.addEventListener('submit', function (e) {e.preventDefault();var email = form.elements.email.value.trim().toLowerCase();var password = form.elements.password.value;fieldError('email', EMAIL.test(email) ? '' : 'Enter a valid email address.');fieldError('password', password ? '' : 'Enter your password.');if (!EMAIL.test(email) || !password) { say('bad', 'Please fix the highlighted fields.'); return; }
busy(true);statusBox.className = 'alert hid';ZamoveApi.request('POST', 'sessions', { email: email, password: password }, { noRedirect401: true })
.then(function (r) {location.replace(safeNext(r.data.user.role));})
.catch(function (err) {form.elements.password.value = '';if (err.status === 401) say('bad', 'Invalid email or password.');else if (err.status === 403) say('bad', err.message);else if (err.status === 422) {Object.keys(err.fieldErrors).forEach(function (f) { fieldError(f, err.fieldErrors[f]); });say('bad', 'Please fix the highlighted fields.');} else if (err.status === 429) say('bad', 'Too many attempts. Wait ' + (err.retryAfter || 60) + ' seconds and try again.');else if (err.network) say('bad', err.message + ' Check your connection and try again.');else say('bad', 'Something went wrong. Please try again.');})
.then(function () { busy(false); });});})();